package mailnotify

import (
	"fmt"
	"strings"

	"github.com/jsfpechar-ops/jsfpecharoperations/go/internal/validation"
)

// Port of the receipt builder in App/app/mail_notify.py: build_completion, with the
// date and check-in helpers of claim.py (_completion_facts) and fmt_date / fmt_date_range
// of validation.py. The fee block is doorFeeBlock (_fee_block, shared with the door-code
// mail). The copy comes from completion_i18n.go. testdata/completion_golden.json is
// generated by App/scripts/go_mailnotify_completion_golden.py.

// ReceiptDetailsMarker is mail.RECEIPT_DETAILS_MARKER: the outbox fills in the guest's
// details at send time (render_receipt_details).
const ReceiptDetailsMarker = "{{receipt_details}}"

// CompletionDoorCode is the door_code dict build_completion reads: the stay's check-in and
// check-out text and, when there is one, the first-use deadline.
type CompletionDoorCode struct {
	Checkin    string `json:"checkin"`
	Checkout   string `json:"checkout"`
	FirstUseBy string `json:"first_use_by"` // "" when none
}

// CompletionInput is build_completion's keyword arguments. Optional values are pointers
// (Python None); Expected of 0 is falsy in Python, so it gives no stay panel row either.
type CompletionInput struct {
	Lang         string
	PropertyName string
	Dates        string
	Host         *Host               // nil when the Python call passes none
	DoorCode     *CompletionDoorCode // nil when no code rides along
	Filled       int
	Expected     *int
	Checkin      string
	Checkout     string
	HostURL      string // "" when none
	Fee          *DoorCodeFee
	SentDetails  bool
}

// CompletionOutput is what build_completion returns. QRSpayd is "" when there is no QR.
type CompletionOutput struct {
	Subject string
	Text    string
	HTML    string
	QRSpayd string
}

// BuildCompletion is build_completion. publicBaseURL is config.PUBLIC_BASE_URL without a
// trailing slash (the logo origin).
func BuildCompletion(publicBaseURL string, in CompletionInput) CompletionOutput {
	lang := in.Lang
	var subject, intro, heading, preheader string
	if in.Fee != nil {
		subject = completionGuestText(lang, "mail_completion_subject_fee",
			Args{"property": in.PropertyName, "total": in.Fee.Total})
		intro = completionGuestText(lang, "mail_completion_intro_fee",
			Args{"property": in.PropertyName, "dates": in.Dates})
		heading = completionGuestText(lang, "mail_completion_heading_fee", nil)
		preheader = completionGuestText(lang, "mail_completion_preheader_fee", nil)
	} else {
		subject = completionGuestText(lang, "mail_completion_subject",
			Args{"property": in.PropertyName})
		intro = completionGuestText(lang, "mail_completion_intro",
			Args{"property": in.PropertyName, "dates": in.Dates})
		heading = completionGuestText(lang, "mail_completion_heading", nil)
		preheader = completionGuestText(lang, "mail_completion_preheader", nil)
	}
	note := completionGuestText(lang, "mail_completion_note", nil)
	footer := GuestFooterLines(lang, in.PropertyName, in.Host)

	// Slot 1: the status. Buttonless unless a fee has a Revolut way.
	blocks := []string{BlockHeading(heading), BlockParagraph(intro, false)}
	textLines := []string{intro}

	// The stay at a glance: counts and property facts only, never a guest's name or document.
	var rows []PanelRow
	if in.Expected != nil && *in.Expected != 0 {
		rows = append(rows, PanelRow{
			Label: completionGuestText(lang, "mail_completion_guests_label", nil),
			Value: completionGuestText(lang, "mail_completion_guests_value",
				Args{"filled": in.Filled, "expected": *in.Expected}),
		})
	}
	if in.Checkin != "" {
		rows = append(rows, PanelRow{Label: completionGuestText(lang, "mail_completion_checkin_label", nil), Value: in.Checkin})
	}
	if in.Checkout != "" {
		rows = append(rows, PanelRow{Label: completionGuestText(lang, "mail_completion_checkout_label", nil), Value: in.Checkout})
	}
	if len(rows) > 0 {
		blocks = append(blocks, BlockPanel(completionGuestText(lang, "mail_completion_panel_title", nil), rows, nil, ""))
		textLines = append(textLines, "")
		for _, r := range rows {
			textLines = append(textLines, r.Label+": "+r.Value)
		}
	}

	// 1122: "What you sent", filled in at send time. The marker is a raw block, as in Python.
	if in.SentDetails {
		blocks = append(blocks, ReceiptDetailsMarker)
		textLines = append(textLines, "", ReceiptDetailsMarker)
	}

	spayd := ""
	if in.Fee != nil {
		feeBlocks, feeText, s := doorFeeBlock(lang, in.Fee)
		blocks = append(blocks, feeBlocks...)
		textLines = append(textLines, "")
		textLines = append(textLines, feeText...)
		spayd = s
	}

	if dc := in.DoorCode; dc != nil {
		codeTitle := completionGuestText(lang, "door_code_title", nil)
		times := completionGuestText(lang, "door_code_times",
			Args{"checkin": dc.Checkin, "checkout": dc.Checkout})
		blocks = append(blocks,
			BlockHeading(codeTitle),
			BlockParagraphSized(doorCodeMarker, false, 22),
			BlockParagraph(times, false),
		)
		textLines = append(textLines, "", codeTitle, doorCodeMarker, times)
		if dc.FirstUseBy != "" {
			firstUse := completionGuestText(lang, "door_code_first_use", Args{"deadline": dc.FirstUseBy})
			blocks = append(blocks, BlockParagraph(firstUse, false))
			textLines = append(textLines, firstUse)
		}
	}

	// Slot 2: one quiet link, for the copied host only.
	if in.HostURL != "" {
		hostAction := completionGuestText(lang, "mail_completion_host_action", nil)
		blocks = append(blocks, BlockQuietLink(in.HostURL, hostAction))
		textLines = append(textLines, "", hostAction+": "+in.HostURL)
	}

	// Slot 3: the closing note.
	blocks = append(blocks, BlockParagraph(note, true))
	textLines = append(textLines, "", note)

	lines := append(textLines, "", "--")
	lines = append(lines, FooterText(footer)...)
	html := Shell(ShellParams{
		PublicBaseURL: publicBaseURL,
		Lang:          lang,
		Title:         in.PropertyName,
		Preheader:     preheader,
		Blocks:        blocks,
		FooterLines:   footer,
	})
	return CompletionOutput{Subject: subject, Text: strings.Join(lines, "\n"), HTML: html, QRSpayd: spayd}
}

// CompletionDateRange is validation.fmt_date_range over two ISO dates: "from – to", or
// whichever end exists.
func CompletionDateRange(from, to string) string {
	start, end := CompletionDate(from), CompletionDate(to)
	if start != "" && end != "" {
		return start + " – " + end
	}
	return start + end
}

// CompletionDate is validation.fmt_date: DD.MM.YYYY, or the input unchanged when it does
// not parse ("" for "").
func CompletionDate(value string) string {
	if d, ok := validation.ParseISODate(value); ok {
		return d.Format("02.01.2006")
	}
	return value
}

// CompletionFacts is claim._completion_facts: the check-in and check-out rows of the stay
// panel. A stay with no hour, or no date, gives the date alone.
func CompletionFacts(lang, dateFrom, dateTo string, checkinHour, checkoutHour *int64) (string, string) {
	return completionMoment(lang, dateFrom, checkinHour, "mail_completion_checkin_value"),
		completionMoment(lang, dateTo, checkoutHour, "mail_completion_checkout_value")
}

func completionMoment(lang, day string, hour *int64, key string) string {
	shown := CompletionDate(day)
	if shown == "" || hour == nil {
		return shown
	}
	return completionGuestText(lang, key, Args{"date": shown, "time": fmt.Sprintf("%02d:00", *hour)})
}
